<?php
declare(strict_types=1);
function pub_storage():string{$root=dirname(__DIR__).'/publication-files';if(is_link($root)||file_exists($root)&&!is_dir($root))crm_fail(503,'Хранилище недоступно.');if(!is_dir($root)&&!mkdir($root,0700))crm_fail(503,'Хранилище недоступно.');$real=realpath($root);if($real!==realpath(dirname(__DIR__)).'/publication-files')crm_fail(503,'Небезопасный путь хранилища.');if(PHP_SAPI!=='cli'){$web=realpath($_SERVER['DOCUMENT_ROOT']??'');if(!$web||$real===$web||str_starts_with($real,$web.'/'))crm_fail(503,'Хранилище должно находиться вне публичного каталога.');}return $real;}
function pub_media_path(array $f):string{if(($f['deleted_at']??null)!==null||($f['kind']??'upload')!=='upload')crm_fail(404,'Файл удалён или хранится у внешнего сервиса.');if(!preg_match('/^[a-f0-9]{64}$/D',$f['storage_key']))crm_fail(404,'Файл не найден.');$p=pub_storage().'/'.$f['storage_key'];if(is_link($p)||!is_file($p)||filesize($p)!==(int)$f['size_bytes']||!hash_equals($f['checksum'],hash_file('sha256',$p)))crm_fail(404,'Файл не найден.');return $p;}
function pub_ini_bytes(string $value):int{$value=trim($value);$n=(float)$value;$unit=strtolower(substr($value,-1));return (int)($n*match($unit){'g'=>1073741824,'m'=>1048576,'k'=>1024,default=>1});}
function pub_storage_info():array{$upload=pub_ini_bytes((string)ini_get('upload_max_filesize'));$post=pub_ini_bytes((string)ini_get('post_max_size'));$limit=min(8388608,$upload>0?$upload:8388608,$post>0?max(1,$post-65536):8388608);$used=(int)crm_query('SELECT COALESCE(SUM(size_bytes),0) FROM nd_publication_media WHERE purged_at IS NULL')->fetchColumn();return ['max_file_bytes'=>$limit,'quota_bytes'=>268435456,'used_bytes'=>$used,'remaining_bytes'=>max(0,268435456-$used),'item_count_limit'=>null,'external_services'=>['RUTUBE','VK Видео','YouTube'],'hosting_note'=>'Количество элементов кейса не ограничено. Действуют показанные лимиты файла/медиатеки и ограничения тарифа хостинга; ошибки записи не скрываются.'];}
function pub_upload():array{
 $limits=pub_storage_info();$f=$_FILES['file']??null;if(!is_array($f)||($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name']))crm_fail(422,'Хостинг не принял файл. Доступный лимит одного файла: '.$limits['max_file_bytes'].' байт. Выберите исходный файл меньшего размера.');$size=filesize($f['tmp_name']);if(!$size||$size>$limits['max_file_bytes'])crm_fail(422,'Файл пустой или превышает текущий лимит '.$limits['max_file_bytes'].' байт.');$name=$f['name'];if(!is_string($name)||mb_strlen($name)>190||preg_match('~[\x00-\x1f/\\\\]~',$name)||str_contains($name,'..'))crm_fail(422,'Проверьте имя файла.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$types=['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp','mp4'=>'video/mp4','webm'=>'video/webm'];if(($types[$ext]??null)!==$mime)crm_fail(422,'Поддерживаются JPG, PNG, WebP, MP4 и WebM; тип проверяется по содержимому.');if(str_starts_with($mime,'image/')){$info=@getimagesize($f['tmp_name']);if(!$info||$info[0]>10000||$info[1]>10000||$info[0]*$info[1]>40000000)crm_fail(422,'Изображение слишком большое или повреждено.');}
 $key=bin2hex(random_bytes(32));$path=pub_storage().'/'.$key;if(!move_uploaded_file($f['tmp_name'],$path))crm_fail(503,'Хостинг не смог записать файл. Проверьте оставшееся место в медиатеке и повторите загрузку; файл не добавлен.');chmod($path,0600);
 try{return crm_atomic(function()use($name,$mime,$size,$path,$key){if((int)crm_query('SELECT COALESCE(SUM(size_bytes),0) FROM nd_publication_media WHERE purged_at IS NULL FOR UPDATE')->fetchColumn()+$size>268435456)crm_fail(422,'Квота медиатеки исчерпана. Уберите неиспользуемые собственные файлы через медиатеку либо увеличьте доступное хранилище.');crm_query('INSERT INTO nd_publication_media(storage_key,display_name,mime,size_bytes,checksum) VALUES (?,?,?,?,?)',[$key,$name,$mime,$size,hash_file('sha256',$path)]);return ['ok'=>true,'file'=>crm_query('SELECT id,kind,external_url,display_name,mime,size_bytes,checksum FROM nd_publication_media WHERE id=?',[(int)db()->lastInsertId()])->fetch(),'storage'=>pub_storage_info()];});}catch(Throwable $e){unlink($path);throw $e;}
}
function pub_external_url(string $url):string{
 if(!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https'||parse_url($url,PHP_URL_USER)!==null||parse_url($url,PHP_URL_PASS)!==null||parse_url($url,PHP_URL_PORT)!==null||parse_url($url,PHP_URL_FRAGMENT)!==null)crm_fail(422,'Нужна HTTPS-ссылка на отдельное видео без паролей или фрагментов.');$host=strtolower(parse_url($url,PHP_URL_HOST)??'');$path=parse_url($url,PHP_URL_PATH)??'';$query=parse_url($url,PHP_URL_QUERY);
 if(in_array($host,['rutube.ru','www.rutube.ru'],true)&&$query===null&&preg_match('~^/video/([a-f0-9]{32})/?$~D',$path,$m))return 'https://rutube.ru/video/'.$m[1].'/';
 if($host==='vkvideo.ru'&&$query===null&&preg_match('~^/video(-?[0-9]+)_([0-9]+)/?$~D',$path,$m))return 'https://vkvideo.ru/video'.$m[1].'_'.$m[2];
 if(in_array($host,['youtube.com','www.youtube.com'],true)&&$path==='/watch'&&is_string($query)&&preg_match('/^v=([A-Za-z0-9_-]{11})$/D',$query,$m))return 'https://www.youtube.com/watch?v='.$m[1];
 if($host==='youtu.be'&&$query===null&&preg_match('~^/([A-Za-z0-9_-]{11})/?$~D',$path,$m))return 'https://www.youtube.com/watch?v='.$m[1];
 crm_fail(422,'Поддерживаются отдельные видео RUTUBE (/video/…), VK Видео (/video…_…) и YouTube (watch?v=… или youtu.be/…). Вставлять HTML или iframe нельзя. Проверяется формат ссылки, без загрузки внешнего сайта.');
}
function pub_external(array $d):array{return crm_idempotent('publication/external',$d,function()use($d){$url=pub_external_url(cc_text($d,'url',2000));$name=cc_text($d,'title',190);crm_query("INSERT INTO nd_publication_media(kind,external_url,display_name,mime,size_bytes,checksum) VALUES ('external',?,?,'video/external',0,?)",[$url,$name,hash('sha256','external:'.$url)]);return ['ok'=>true,'file'=>crm_query('SELECT id,kind,external_url,display_name,mime,size_bytes,checksum FROM nd_publication_media WHERE id=?',[(int)db()->lastInsertId()])->fetch(),'network_validation'=>false];});}
function pub_media_delete(array $d):array{
 $id=cc_id($d['media_id']??null);$reason=cc_text($d,'reason',3000);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите удаление неиспользуемой копии из медиатеки.');
 $f=crm_atomic(function()use($id,$reason){$f=crm_query('SELECT * FROM nd_publication_media WHERE id=? FOR UPDATE',[$id])->fetch();if(!$f)crm_fail(404,'Файл не найден.');$refs=crm_query("SELECT v.id,p.id AS publication_id,p.state,p.published_version_id,p.order_id,g.state AS permission_state FROM nd_publication_versions v JOIN nd_publications p ON p.id=v.publication_id LEFT JOIN nd_publication_permissions g ON g.version_id=v.id WHERE JSON_CONTAINS(v.body_json,JSON_OBJECT('media',JSON_ARRAY(JSON_OBJECT('id',CAST(? AS UNSIGNED)))))",[$id])->fetchAll();foreach($refs as $r){if($r['state']==='PUBLISHED'&&(int)$r['published_version_id']===(int)$r['id']||in_array($r['permission_state'],['REQUESTED','GRANTED'],true))crm_fail(409,'Файл используется в публикации или неотозванном разрешении. Сначала снимите публикацию и разрешите связанные обязательства.');if($r['order_id']&&crm_query("SELECT order_id FROM nd_lc_order_flow WHERE order_id=? AND case_state IN ('PAUSED','DISPUTED')",[$r['order_id']])->fetchColumn())crm_fail(409,'По связанному заказу есть пауза или спор. Копия сохраняется.');}crm_query('UPDATE nd_publication_media SET deleted_at=COALESCE(deleted_at,UTC_TIMESTAMP()) WHERE id=?',[$id]);lc_audit(['type'=>'owner','id'=>1],'publication_media',$id,'deletion_requested',null,['reason'=>$reason,'original_customer_uploads_affected'=>false]);return $f;});
 if($f['kind']==='upload'){$key=$f['storage_key'];if(!preg_match('/^[a-f0-9]{64}$/D',$key))crm_fail(503,'Небезопасный путь файла.');$path=pub_storage().'/'.$key;if(is_link($path)||file_exists($path)&&!unlink($path))crm_fail(503,'Файл закрыт от выдачи, но хостинг пока не удалил копию. Повторите удаление; место ещё учитывается в квоте.');}crm_query('UPDATE nd_publication_media SET purged_at=COALESCE(purged_at,UTC_TIMESTAMP()) WHERE id=?',[$id]);return ['ok'=>true,'purged'=>true,'original_customer_uploads_affected'=>false,'storage'=>pub_storage_info()];
}

function pub_stream(array $file):never{$path=pub_media_path($file);$size=(int)$file['size_bytes'];$start=0;$end=$size-1;$range=$_SERVER['HTTP_RANGE']??'';header('Content-Type: '.$file['mime']);header('X-Content-Type-Options: nosniff');header('Content-Disposition: inline; filename="media-'.$file['id'].'"');header('Accept-Ranges: bytes');header('Cache-Control: no-store');if($range!==''){if(!preg_match('/^bytes=([0-9]*)-([0-9]*)$/D',$range,$m)||$m[1]===''&&$m[2]===''){http_response_code(416);header('Content-Range: bytes */'.$size);exit;}if($m[1]===''){$start=max(0,$size-(int)$m[2]);}else{$start=(int)$m[1];if($m[2]!=='')$end=min($end,(int)$m[2]);}if($start>$end||$start>=$size){http_response_code(416);header('Content-Range: bytes */'.$size);exit;}http_response_code(206);header('Content-Range: bytes '.$start.'-'.$end.'/'.$size);}header('Content-Length: '.($end-$start+1));$h=fopen($path,'rb');fseek($h,$start);$left=$end-$start+1;while($left>0&&!feof($h)){$bytes=fread($h,min(65536,$left));if($bytes===false||$bytes==='')break;echo $bytes;$left-=strlen($bytes);}fclose($h);exit;}
